<template>
    <div>
        <Head title="Charts" />

        <div class="text-center">
            <h3 class="title">Chart.js</h3>
            <p class="category">
                Charts from the Material Dashboard template, built with
                <a href="https://www.chartjs.org/docs/latest/" target="_blank" rel="noopener noreferrer">Chart.js</a>.
            </p>
        </div>

        <div class="row">
            <div v-for="chart in charts" :key="chart.id" class="md:col-4">
                <ChartCard :title="chart.title" :color="chart.color" :description="chart.description">
                    <template #chart>
                        <div class="charts-demo-canvas">
                            <Chart
                                :canva-id="chart.id"
                                :type="chart.type"
                                :data="chart.data"
                                :options="chart.options"
                                role="img"
                                :aria-label="chart.title"
                            />
                        </div>
                    </template>
                </ChartCard>
            </div>
        </div>
        <div class="row">
            <div v-for="chart in detailedCharts.slice(0, 2)" :key="chart.id" class="md:col-6">
                <Card :icon="chart.icon" :card-header-class="`card-header-${chart.color}`">
                    <template #header>
                        <h4 class="card-title">{{ chart.title }} <small> - {{ chart.subtitle }}</small></h4>
                    </template>
                    <div class="charts-demo-canvas charts-demo-canvas-large">
                        <Chart :canva-id="chart.id" :type="chart.type" :data="chart.data" :options="chart.options" role="img" :aria-label="chart.title" />
                    </div>
                </Card>
            </div>
        </div>

        <div class="row">
            <div class="md:col-7">
                <Card :icon="colouredLines.icon" :card-header-class="`card-header-${colouredLines.color}`">
                    <template #header>
                        <h4 class="card-title">{{ colouredLines.title }} <small> - {{ colouredLines.subtitle }}</small></h4>
                    </template>
                    <div class="charts-demo-canvas charts-demo-canvas-large">
                        <Chart :canva-id="colouredLines.id" :type="colouredLines.type" :data="colouredLines.data" :options="colouredLines.options" role="img" :aria-label="`${colouredLines.title}: three rounded line series`" />
                    </div>
                </Card>
            </div>
            <div class="md:col-5">
                <Card class="card-chart" title="Pie Chart" icon="pie_chart" card-header-class="card-header-danger">
                    <div class="charts-demo-canvas charts-demo-canvas-pie">
                        <Chart canva-id="demo-preferences-pie" type="pie" :data="pieData" :options="pieOptions" :plugins="piePlugins" role="img" aria-label="Apple 62%, Windows Phone 32%, Samsung 6%" />
                    </div>
                    <template #footer>
                        <div>
                            <h6 class="card-category">Legend</h6>
                            <ul class="list-unstyled d-flex flex-wrap gap-3 mb-0">
                                <li v-for="item in pieLegend" :key="item.label" class="d-flex align-items-center gap-1">
                                    <span class="charts-demo-legend-dot" :class="`bg-${item.color}`" aria-hidden="true"></span>
                                    {{ item.label }}
                                </li>
                            </ul>
                        </div>
                    </template>
                </Card>
            </div>
        </div>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';
import Chart from '@scaffold/components/Chart.vue';
import ChartCard from '@scaffold/components/ChartCard.vue';

function chartOptions(type) {
    const tickColor = 'rgba(255, 255, 255, .8)';

    return {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 700 },
        plugins: { legend: { display: false } },
        scales: {
            x: {
                border: { display: false },
                grid: { display: false, drawTicks: false },
                ticks: {
                    color: tickColor,
                    autoSkip: false,
                    maxRotation: 0,
                    padding: 6,
                    callback(value) {
                        const label = this.getLabelForValue(value);
                        return type === 'bar' && this.chart.width < 400 ? label.charAt(0) : label;
                    },
                },
            },
            y: {
                min: 0,
                max: type === 'bar' ? 1000 : 50,
                border: { display: false, dash: [2, 2] },
                grid: { color: 'rgba(255, 255, 255, .2)', drawTicks: false },
                ticks: { color: tickColor, padding: 6, stepSize: type === 'bar' ? 200 : 10 },
            },
        },
    };
}

function themeColor(context, name) {
    return getComputedStyle(context.chart.canvas).getPropertyValue(`--material-${name}`).trim()
        || { info: '#00bcd4', danger: '#f44336', warning: '#ff9800' }[name];
}

function detailedOptions(type) {
    const options = chartOptions(type);
    const foreground = context => getComputedStyle(context.chart.canvas).color;
    options.scales.x.ticks.color = foreground;
    options.scales.y.ticks.color = foreground;
    options.scales.y.max = 1000;
    options.scales.y.ticks.stepSize = 200;
    options.scales.y.grid.color = 'rgba(128, 128, 128, .2)';
    return options;
}

function detailedChart({ labels, series, ...chart }) {
    return {
        ...chart,
        data: {
            labels,
            datasets: series.map((values, index) => ({
                label: `Series ${index + 1}`,
                data: values,
                borderColor: context => themeColor(context, ['info', 'danger', 'warning'][index]),
                backgroundColor: context => themeColor(context, ['info', 'danger', 'warning'][index]),
                borderWidth: chart.type === 'line' ? 3 : 0,
                pointRadius: 4,
                pointBorderWidth: 0,
                pointHoverRadius: 6,
                tension: 0.35,
                fill: false,
                maxBarThickness: 10,
            })),
        },
        options: detailedOptions(chart.type),
    };
}

const percentageLabels = {
    id: 'demo-percentage-labels',
    afterDatasetsDraw(chart) {
        const { ctx } = chart;
        const values = chart.data.datasets[0].data;
        const total = values.reduce((sum, value) => sum + value, 0);
        if (!total) {
            return;
        }
        ctx.save();
        ctx.fillStyle = '#fff';
        ctx.font = '400 14px Roboto, sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        chart.getDatasetMeta(0).data.forEach((arc, index) => {
            if (!chart.getDataVisibility(index) || !arc.circumference) {
                return;
            }
            const { x, y } = arc.getCenterPoint();
            ctx.fillText(`${Math.round(values[index] / total * 100)}%`, x, y);
        });
        ctx.restore();
    },
};

export default {
    name: 'ChartsDemo',
    components: { Card, Chart, ChartCard, Head },
    layout: { pageTitle: 'Charts' },
    data() {
        return {
            detailedCharts: [
                {
                    id: 'demo-coloured-line', title: 'Coloured Line Chart', subtitle: 'Rounded',
                    icon: 'timeline', color: 'info', type: 'line',
                    // The template has eleven values and ten year labels. Keep the final point unlabelled.
                    labels: ["'06", "'07", "'08", "'09", "'10", "'11", "'12", "'13", "'14", "'15", ''],
                    series: [[287, 480, 290, 554, 690, 690, 500, 752, 650, 900, 944]],
                },
                {
                    id: 'demo-multiple-bars', title: 'Multiple Bars Chart', subtitle: 'Bar Chart',
                    icon: 'insert_chart', color: 'rose', type: 'bar',
                    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'Mai', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
                    series: [
                        [542, 443, 320, 780, 553, 453, 326, 434, 568, 610, 756, 895],
                        [412, 243, 280, 580, 453, 353, 300, 364, 368, 410, 636, 695],
                    ],
                },
                {
                    id: 'demo-coloured-bars', title: 'Coloured Bars Chart', subtitle: 'Rounded',
                    icon: 'timeline', color: 'info', type: 'line',
                    labels: ["'06", "'07", "'08", "'09", "'10", "'11", "'12", "'13", "'14", "'15", ''],
                    series: [
                        [287, 385, 490, 554, 586, 698, 695, 752, 788, 846, 944],
                        [67, 152, 143, 287, 335, 435, 437, 539, 542, 544, 647],
                        [23, 113, 67, 190, 239, 307, 308, 439, 410, 410, 509],
                    ],
                },
            ].map(detailedChart),
            pieData: {
                labels: ['Apple', 'Windows Phone', 'Samsung'],
                datasets: [{
                    data: [62, 32, 6],
                    backgroundColor: context => themeColor(context, ['info', 'danger', 'warning'][context.dataIndex]),
                    borderWidth: 0,
                }],
            },
            pieOptions: {
                responsive: true,
                maintainAspectRatio: false,
                rotation: 0,
                animation: { duration: 700 },
                plugins: {
                    legend: { display: false },
                    tooltip: { callbacks: { label: context => `${context.label}: ${context.parsed}%` } },
                },
            },
            piePlugins: [percentageLabels],
            pieLegend: [{ label: 'Apple', color: 'info' }, { label: 'Samsung', color: 'warning' }, { label: 'Windows Phone', color: 'danger' }],
            charts: [
                {
                    id: 'demo-rounded-line',
                    title: 'Rounded Line Chart',
                    description: 'Line Chart',
                    color: 'rose',
                    type: 'line',
                    labels: ['M', 'T', 'W', 'T', 'F', 'S', 'S'],
                    values: [12, 17, 7, 17, 23, 18, 38],
                    tension: 0.35,
                    pointRadius: 0,
                },
                {
                    id: 'demo-straight-lines',
                    title: 'Straight Lines Chart',
                    description: 'Line Chart with Points',
                    color: 'warning',
                    type: 'line',
                    labels: ["'07", "'08", "'09", "'10", "'11", "'12", "'13", "'14", "'15"],
                    values: [10, 16, 8, 13, 20, 15, 20, 34, 30],
                    tension: 0,
                    pointRadius: 4,
                },
                {
                    id: 'demo-simple-bars',
                    title: 'Simple Bar Chart',
                    description: 'Bar Chart',
                    color: 'info',
                    type: 'bar',
                    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'Mai', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
                    values: [542, 443, 320, 780, 553, 453, 326, 434, 568, 610, 756, 895],
                    pointRadius: 0,
                    tension: 0,
                },
            ].map(({ labels, values, tension, pointRadius, ...chart }) => ({
                ...chart,
                data: {
                    labels,
                    datasets: [{
                        label: chart.title,
                        data: values,
                        borderColor: 'rgba(255, 255, 255, .85)',
                        backgroundColor: 'rgba(255, 255, 255, .85)',
                        borderWidth: chart.type === 'line' ? 4 : 0,
                        pointBorderWidth: 0,
                        pointRadius,
                        pointHoverRadius: chart.type === 'line' ? 5 : 0,
                        pointHitRadius: 10,
                        tension,
                        fill: false,
                        maxBarThickness: 10,
                    }],
                },
                options: chartOptions(chart.type),
            })),
        };
    },
    computed: {
        colouredLines() {
            return this.detailedCharts[2];
        },
    },
};
</script>

<style scoped>
.charts-demo-canvas {
    position: relative;
    height: 160px;
}

.charts-demo-canvas-large {
    height: 300px;
}

.charts-demo-canvas-pie {
    height: 230px;
}

.charts-demo-legend-dot {
    width: 12px;
    height: 12px;
    flex-shrink: 0;
    border-radius: 50%;
}
</style>
